enum MeshCapabilityBits : uint16_t
{
  CAP_VIB = 1 << 0,
  CAP_PIR = 1 << 1,
  CAP_GAS = 1 << 2,
  CAP_DHT = 1 << 3,
  CAP_SIM = 1 << 4,
  CAP_SIREN = 1 << 5,
  CAP_SMS = 1 << 6,
  CAP_WEB = 1 << 7
};

