bool getSignalCSQ(int &csq, int &rssiDbm)
{
  String resp;
  if (!sendAtWait("AT+CSQ", "OK", 1200, &resp))
    return false;
  int p = resp.indexOf("+CSQ:");
  if (p < 0)
    return false;
  int comma = resp.indexOf(',', p);
  if (comma < 0)
    return false;
  String s = resp.substring(p + 5, comma);
  s.trim();
  csq = s.toInt();
  if (csq == 99)
  {
    rssiDbm = -1;
    return true;
  }
  // RSSI dBm approx: rssi = -113 + 2*csq
  rssiDbm = -113 + 2 * csq;
  return true;
}

